<?php
namespace Tests\Feature;use App\Models\{Device,DeviceAccessAssignment,Organization,ResourceEditingSession,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
final class ConcurrentEditingDetectionTest extends TestCase{use RefreshDatabase;private function fixture():array{$o=Organization::create(['name'=>'Presence','slug'=>'presence']);$a=User::factory()->create(['organization_id'=>$o->id,'role'=>'staff','status'=>'active']);$b=User::factory()->create(['organization_id'=>$o->id,'role'=>'staff','status'=>'active']);$v=User::factory()->create(['organization_id'=>$o->id,'role'=>'staff','status'=>'active']);$d=$o->devices()->create(['name'=>'Pump','external_id'=>'presence-pump','status'=>'online','type'=>'sensor','protocol'=>'mqtt']);foreach([[$a,'full_access'],[$b,'full_access'],[$v,'viewer']]as[$u,$level])DeviceAccessAssignment::create(['device_id'=>$d->id,'user_id'=>$u->id,'access_level'=>$level]);return compact('a','b','v','d');}
public function test_editors_start_heartbeat_list_and_release_advisory_sessions():void{$f=$this->fixture();$root="/api/resources/device/{$f['d']->id}/editing-sessions";$first=$this->actingAs($f['a'])->postJson($root)->assertCreated()->assertJsonPath('data.lease.ttlSeconds',90)->json('data.lease.token');$second=$this->actingAs($f['a'])->postJson($root)->assertCreated()->json('data.lease.token');$this->assertNotSame($first,$second);$this->actingAs($f['b'])->postJson($root)->assertCreated();$this->actingAs($f['a'])->getJson($root)->assertOk()->assertJsonCount(3,'data')->assertJsonPath('data.0.sameUser',true);$this->actingAs($f['a'])->postJson("$root/$first/heartbeat")->assertOk();$this->actingAs($f['b'])->deleteJson("$root/$first")->assertNotFound();$this->actingAs($f['a'])->deleteJson("$root/$first")->assertNoContent();$this->assertDatabaseMissing('resource_editing_sessions',['id'=>$first]);}
public function test_viewer_foreign_session_and_expired_rows_are_safe():void{$f=$this->fixture();$root="/api/resources/device/{$f['d']->id}/editing-sessions";$this->actingAs($f['v'])->postJson($root)->assertNotFound();$token=$this->actingAs($f['a'])->postJson($root)->assertCreated()->json('data.lease.token');ResourceEditingSession::whereKey($token)->update(['expires_at'=>now()->subSecond()]);$this->actingAs($f['a'])->getJson($root)->assertOk()->assertJsonCount(0,'data');$this->assertDatabaseCount('resource_revisions',0);}}
